13	/// A `pyproject.toml` manifest editor supporting PEP 621, Poetry, and Flit schemas with 100% CST comment preservation.
14	pub struct PyprojectToml {
15	    path: PathBuf,
16	    absolute: PathBuf,
17	    role: ManifestRole,
18	    document: toml_edit::DocumentMut,
19	    fingerprint: crate::common::FormatFingerprint,
20	}
21	
22	impl PyprojectToml {
23	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
24	        let rel_path = decl.path.clone();
25	        let abs_path = ctx.workspace_root.join(&rel_path);
26	
27	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
28	            path: rel_path.clone(),
29	            message: e.to_string(),
30	        })?;
31	
32	        let fingerprint = crate::common::FormatFingerprint::detect(&content);
33	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
34	
35	        let doc: toml_edit::DocumentMut =
36	            clean_content
37	                .parse()
38	                .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
39	                    path: rel_path.clone(),
40	                    format: ManifestFormat::PyprojectToml,
41	                    message: e.to_string(),
42	                })?;
43	
44	        Ok(Self {
45	            path: rel_path,
46	            absolute: abs_path,
47	            role: decl.role.clone(),
48	            document: doc,
49	            fingerprint,
50	        })
51	    }
52	
53	    fn render(&self) -> String {
54	        self.fingerprint.apply(&self.document.to_string())
55	    }
56	}
