58	/// Extracts a package name from an already-parsed `pyproject.toml`
59	/// document, checking (1) PEP 621 `[project].name`, (2) Poetry
60	/// `[tool.poetry].name`, (3) Flit `[tool.flit.metadata].module`, in that
61	/// order. Pure and I/O-free -- see `crate::cargo::cargo_package_name`'s
62	/// doc comment for why this exists as a standalone function rather than
63	/// only living inside [`Manifest::package_name`].
64	pub fn python_package_name(doc: &toml_edit::DocumentMut) -> Option<&str> {
65	    doc.get("project")
66	        .and_then(|p| p.get("name"))
67	        .and_then(|n| n.as_str())
68	        .or_else(|| {
69	            doc.get("tool")
70	                .and_then(|t| t.get("poetry"))
71	                .and_then(|p| p.get("name"))
72	                .and_then(|n| n.as_str())
73	        })
74	        .or_else(|| {
75	            doc.get("tool")
76	                .and_then(|t| t.get("flit"))
77	                .and_then(|f| f.get("metadata"))
78	                .and_then(|m| m.get("module"))
79	                .and_then(|n| n.as_str())
80	        })
81	}
