83	/// [`crate::read_identity`]'s `pyproject.toml` implementation: parses
84	/// `source` and extracts a package name (PEP 621, falling back to Poetry
85	/// then Flit -- see [`python_package_name`]) plus a
86	/// [`crate::VersionSource::Literal`] version (PEP 621 `project.version`,
87	/// falling back to Poetry's `tool.poetry.version`). Python has no
88	/// workspace-inherited-version concept analogous to Cargo's, and a Flit or
89	/// PEP 621 `dynamic = ["version"]` package has no static version to report
90	/// at all, so both fall through to `None`.
91	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
92	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
93	    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
94	        path: path.to_path_buf(),
95	        format: ManifestFormat::PyprojectToml,
96	        message: e.to_string(),
97	    })?;
98	
99	    let name = python_package_name(&doc).map(str::to_string);
100	    let version = doc
101	        .get("project")
102	        .and_then(|p| p.get("version"))
103	        .and_then(|v| v.as_str())
104	        .or_else(|| {
105	            doc.get("tool")
106	                .and_then(|t| t.get("poetry"))
107	                .and_then(|p| p.get("version"))
108	                .and_then(|v| v.as_str())
109	        })
110	        .map(|s| crate::VersionSource::Literal(s.to_string()));
111	
112	    Ok(crate::ManifestIdentity { name, version })
113	}
