115	/// A parsed PEP 508 dependency specifier, e.g.
116	/// `"requests[security,socks]>=2.0; python_version >= '3.8'"`.
117	///
118	/// Previously decomposed independently at three call sites in this module
119	/// (`iter_dependencies`, `update_dependency_spec`,
120	/// `update_optional_dependencies`), each hand-rolling the same
121	/// marker-split / operator-split / extras-split sequence -- this type is
122	/// the single implementation all three now share.
123	///
124	/// `render` produces a normalized textual form (no space around `[...]`,
125	/// extras comma-joined with no interior space, no space between the
126	/// name/extras and the version spec, and a single `;` directly before the
127	/// marker with no extra whitespace). This is not necessarily byte-identical
128	/// to arbitrary input formatting, but `Requirement::parse(&r.render())`
129	/// always reproduces a `Requirement` equal to `r` when `r` itself came from
130	/// `parse` -- see the `requirement_parse_render_parse_is_idempotent`
131	/// property test.
132	#[derive(Clone, Debug, PartialEq, Eq)]
133	pub struct Requirement {
134	    pub name: String,
135	    pub extras: Vec<String>,
136	    /// The version-constraint clause(s) verbatim (e.g. `">=1.0,<2.0"` or
137	    /// `"==1.2.3"`) -- `None` when the requirement carries no version
138	    /// constraint at all (a bare name, optionally with extras/marker).
139	    pub spec: Option<String>,
140	    /// The marker expression (without the leading `;` or surrounding
141	    /// whitespace), e.g. `"python_version >= '3.8'"` -- `None` when absent.
142	    pub marker: Option<String>,
143	}
144	
145	impl Requirement {
146	    /// Parses a single PEP 508 requirement string. Returns `None` when no
147	    /// package name can be extracted (e.g. an empty string, or a string
148	    /// that is entirely a marker/version clause with nothing before it).
149	    pub fn parse(s: &str) -> Option<Self> {
150	        let s = s.trim();
151	
152	        let mut halves = s.splitn(2, ';');
153	        let spec_part = halves.next().unwrap_or("").trim();
154	        let marker = halves
155	            .next()
156	            .map(str::trim)
157	            .filter(|m| !m.is_empty())
158	            .map(str::to_string);
159	
160	        let op_idx = spec_part.find(['<', '>', '=', '!', '~']);
161	        let (pkg_part, spec) = match op_idx {
162	            Some(idx) => (spec_part[..idx].trim(), Some(spec_part[idx..].trim().to_string())),
163	            None => (spec_part, None),
164	        };
165	
166	        let (name, extras) = match pkg_part.find('[') {
167	            Some(idx) => {
168	                let name = pkg_part[..idx].trim().to_string();
169	                let extras_str = pkg_part[idx..].trim_start_matches('[').trim_end_matches(']');
170	                let extras = extras_str
171	                    .split(',')
172	                    .map(str::trim)
173	                    .filter(|e| !e.is_empty())
174	                    .map(str::to_string)
175	                    .collect();
176	                (name, extras)
177	            }
178	            None => (pkg_part.trim().to_string(), Vec::new()),
179	        };
180	
181	        if name.is_empty() {
182	            return None;
183	        }
184	
185	        Some(Requirement {
186	            name,
187	            extras,
188	            spec,
189	            marker,
190	        })
191	    }
192	
193	    /// Renders back to PEP 508 text -- see the struct's doc comment for the
194	    /// normalization this applies relative to arbitrary input formatting.
195	    pub fn render(&self) -> String {
196	        let mut out = self.name.clone();
197	        if !self.extras.is_empty() {
198	            out.push('[');
199	            out.push_str(&self.extras.join(","));
200	            out.push(']');
201	        }
202	        if let Some(spec) = &self.spec {
203	            out.push_str(spec);
204	        }
205	        if let Some(marker) = &self.marker {
206	            out.push(';');
207	            out.push_str(marker);
208	        }
209	        out
210	    }
211	}
