219	impl Manifest for PyprojectToml {
220	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
221	        let content = self.render();
222	        atomic_write(&self.absolute, &content, permit).map_err(|e| ManifestError::Write {
223	            path: self.path.clone(),
224	            message: e.to_string(),
225	        })?;
226	        crate::record_persist_call();
227	        Ok(())
228	    }
229	
230	    fn path(&self) -> &Path {
231	        &self.path
232	    }
233	
234	    fn ecosystem(&self) -> Ecosystem {
235	        Ecosystem::Pypi
236	    }
237	
238	    fn role(&self) -> ManifestRole {
239	        self.role.clone()
240	    }
241	
242	    fn package_name(&self) -> Result<String, ManifestError> {
243	        python_package_name(&self.document)
244	            .map(|s| s.to_string())
245	            .ok_or_else(|| ManifestError::MissingField {
246	                path: self.path.clone(),
247	                field: "project.name / tool.poetry.name / tool.flit.metadata.module",
248	            })
249	    }
250	
251	    fn current_version(&self) -> Result<Version, ManifestError> {
252	        // 1. PEP 621 [project].version
253	        let raw_ver = self
254	            .document
255	            .get("project")
256	            .and_then(|p| p.get("version"))
257	            .and_then(|v| v.as_str())
258	            // 2. Poetry [tool.poetry].version
259	            .or_else(|| {
260	                self.document
261	                    .get("tool")
262	                    .and_then(|t| t.get("poetry"))
263	                    .and_then(|p| p.get("version"))
264	                    .and_then(|v| v.as_str())
265	            })
266	            // 3. Flit [tool.flit.metadata].version
267	            .or_else(|| {
268	                self.document
269	                    .get("tool")
270	                    .and_then(|t| t.get("flit"))
271	                    .and_then(|f| f.get("metadata"))
272	                    .and_then(|m| m.get("version"))
273	                    .and_then(|v| v.as_str())
274	            });
275	
276	        let raw = raw_ver.ok_or_else(|| ManifestError::MissingField {
277	            path: self.path.clone(),
278	            field: "project.version / tool.poetry.version",
279	        })?;
280	
281	        Version::parse(raw, VersionGrammar::Pep440).map_err(|e| ManifestError::InvalidVersion {
282	            path: self.path.clone(),
283	            raw: raw.to_string(),
284	            source: e,
285	        })
286	    }
287	
288	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
289	        let new_ver = v.render();
290	
291	        let has_project_version = self.document.get("project").and_then(|p| p.get("version")).is_some();
292	
293	        if has_project_version {
294	            if let Some(proj) = self.document.get_mut("project").and_then(|p| p.as_table_like_mut()) {
295	                crate::common::set_scalar_preserving_decor(proj, "version", new_ver);
296	            }
297	        } else if let Some(poetry) = self
298	            .document
299	            .get_mut("tool")
300	            .and_then(|t| t.get_mut("poetry"))
301	            .and_then(|p| p.as_table_like_mut())
302	        {
303	            crate::common::set_scalar_preserving_decor(poetry, "version", new_ver);
304	        } else if let Some(flit) = self
305	            .document
306	            .get_mut("tool")
307	            .and_then(|t| t.get_mut("flit"))
308	            .and_then(|f| f.get_mut("metadata"))
309	            .and_then(|m| m.as_table_like_mut())
310	        {
311	            crate::common::set_scalar_preserving_decor(flit, "version", new_ver);
312	        } else {
313	            self.document["project"]["version"] = value(new_ver);
314	        }
315	
316	        Ok(())
317	    }
318	
319	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
320	        let mut entries = Vec::new();
321	
322	        // 1. PEP 621 [project].dependencies (array of requirement strings)
323	        if let Some(deps) = self
324	            .document
325	            .get("project")
326	            .and_then(|p| p.get("dependencies"))
327	            .and_then(|d| d.as_array())
328	        {
329	            for item in deps {
330	                if let Some(full_req_str) = item.as_str() {
331	                    if let Some(req) = Requirement::parse(full_req_str) {
332	                        let req_str = req.spec.clone().unwrap_or_else(|| "*".to_string());
333	                        let parsed_req_str = req.spec.as_deref().unwrap_or(">=0.0.0");
334	                        if let Ok(spec) = VersionReq::parse(parsed_req_str, Ecosystem::Pypi) {
335	                            entries.push(DependencyEntry {
336	                                name: req.name.clone(),
337	                                inherited: false,
338	                                kind: DepKind::Runtime,
339	                                spec: DepSpec::Range(spec, req_str),
340	                            });
341	                        }
342	                    }
343	                }
344	            }
345	        }
346	
347	        // 2. Poetry [tool.poetry.dependencies]
348	        if let Some(table) = self
349	            .document
350	            .get("tool")
351	            .and_then(|t| t.get("poetry"))
352	            .and_then(|p| p.get("dependencies"))
353	            .and_then(|d| d.as_table_like())
354	        {
355	            for (name, item) in table.iter() {
356	                if name == "python" {
357	                    continue;
358	                }
359	                let raw_req = match item {
360	                    toml_edit::Item::Value(toml_edit::Value::String(s)) => Some(s.value().as_str()),
361	                    toml_edit::Item::Value(toml_edit::Value::InlineTable(t)) => {
362	                        t.get("version").and_then(|v| v.as_str())
363	                    }
364	                    _ => None,
365	                };
366	
367	                if let Some(req_str) = raw_req {
368	                    if let Ok(spec) = VersionReq::parse(req_str, Ecosystem::Pypi) {
369	                        entries.push(DependencyEntry {
370	                            name: name.to_string(),
371	                            inherited: false,
372	                            kind: DepKind::Runtime,
373	                            spec: DepSpec::Range(spec, req_str.to_string()),
374	                        });
375	                    }
376	                }
377	            }
378	        }
379	
380	        Box::new(entries.into_iter())
381	    }
382	
383	    fn update_dependency_spec(
384	        &mut self,
385	        name: &str,
386	        kind: DepKind,
387	        new: DepSpec,
388	        _permit: &ApplyPermit,
389	    ) -> Result<(), ManifestError> {
390	        let new_spec_str = match new {
391	            DepSpec::Range(req, _) => req.render().to_string(),
392	            DepSpec::Exact(v) => format!("=={}", v.render()),
393	            _ => return Ok(()),
394	        };
395	
396	        let mut updated = false;
397	
398	        // 1. Update PEP 621 [project].dependencies array entries if present
399	        if let Some(deps) = self
400	            .document
401	            .get_mut("project")
402	            .and_then(|p| p.get_mut("dependencies"))
403	            .and_then(|d| d.as_array_mut())
404	        {
405	            for idx in 0..deps.len() {
406	                if let Some(full_req) = deps.get(idx).and_then(|item| item.as_str()) {
407	                    let Some(req) = Requirement::parse(full_req) else {
408	                        continue;
409	                    };
410	                    if normalize_pypi_package_name(&req.name) == normalize_pypi_package_name(name) {
411	                        let formatted_spec = if new_spec_str.starts_with(['<', '>', '=', '!', '~']) {
412	                            new_spec_str.clone()
413	                        } else {
414	                            format!(">={new_spec_str}")
415	                        };
416	                        let new_req = Requirement {
417	                            name: req.name.clone(),
418	                            extras: req.extras.clone(),
419	                            spec: Some(formatted_spec),
420	                            marker: req.marker.clone(),
421	                        };
422	                        deps.replace(idx, new_req.render());
423	                        updated = true;
424	                        break;
425	                    }
426	                }
427	            }
428	        }
429	
430	        // 2. Update Poetry dependencies if present (preserving inline tables if used)
431	        if let Some(table) = self
432	            .document
433	            .get_mut("tool")
434	            .and_then(|t| t.get_mut("poetry"))
435	            .and_then(|p| p.get_mut("dependencies"))
436	            .and_then(|d| d.as_table_like_mut())
437	        {
438	            if let Some(existing) = table.get_mut(name) {
439	                match existing {
440	                    toml_edit::Item::Value(toml_edit::Value::InlineTable(ref mut inline)) => {
441	                        inline.insert("version", toml_edit::Value::from(new_spec_str.as_str()));
442	                    }
443	                    _ => {
444	                        table.insert(name, value(new_spec_str));
445	                    }
446	                }
447	                updated = true;
448	            }
449	        }
450	
451	        if !updated {
452	            return Err(ManifestError::DependencyNotFound {
453	                path: self.path.clone(),
454	                name: name.to_string(),
455	                kind,
456	            });
457	        }
458	
459	        Ok(())
460	    }
