462	    fn is_publishable(&self) -> bool {
463	        // A pyproject.toml without [project].name or [tool.poetry].name is a
464	        // workspace root or build-system-only file — not a publishable package.
465	        let has_pep621_name = self
466	            .document
467	            .get("project")
468	            .and_then(|p| p.get("name"))
469	            .and_then(|n| n.as_str())
470	            .is_some();
471	        let has_poetry_name = self
472	            .document
473	            .get("tool")
474	            .and_then(|t| t.get("poetry"))
475	            .and_then(|p| p.get("name"))
476	            .and_then(|n| n.as_str())
477	            .is_some();
478	        has_pep621_name || has_poetry_name
479	    }
480	
481	    fn publish_targets(&self) -> Vec<PublishTarget> {
482	        if !self.is_publishable() {
483	            return vec![PublishTarget::None];
484	        }
485	        vec![PublishTarget::Pypi { index: None }]
486	    }
487	
488	    fn update_optional_dependencies(
489	        &mut self,
490	        updates: &[(String, Version)],
491	        _permit: &ApplyPermit,
492	    ) -> Result<(), ManifestError> {
493	        if updates.is_empty() {
494	            return Ok(());
495	        }
496	
497	        // [project.optional-dependencies] is a table of group_name → [PEP 508 strings].
498	        // Collect the table keys first to avoid borrow conflicts.
499	        let group_keys: Vec<String> = self
500	            .document
501	            .get("project")
502	            .and_then(|p| p.get("optional-dependencies"))
503	            .and_then(|od| od.as_table_like())
504	            .map(|t| t.iter().map(|(k, _)| k.to_string()).collect())
505	            .unwrap_or_default();
506	
507	        for group_key in &group_keys {
508	            let Some(arr) = self
509	                .document
510	                .get_mut("project")
511	                .and_then(|p| p.get_mut("optional-dependencies"))
512	                .and_then(|od| od.get_mut(group_key.as_str()))
513	                .and_then(|g| g.as_array_mut())
514	            else {
515	                continue;
516	            };
517	
518	            for idx in 0..arr.len() {
519	                let Some(full_req) = arr.get(idx).and_then(|item| item.as_str()) else {
520	                    continue;
521	                };
522	                let Some(req) = Requirement::parse(full_req) else {
523	                    continue;
524	                };
525	
526	                if let Some((_dep_name, new_ver)) = updates.iter().find(|(dep_name, _)| {
527	                    normalize_pypi_package_name(dep_name) == normalize_pypi_package_name(&req.name)
528	                }) {
529	                    let new_req = Requirement {
530	                        name: req.name.clone(),
531	                        extras: req.extras.clone(),
532	                        spec: Some(format!(">={}", new_ver.render())),
533	                        marker: req.marker.clone(),
534	                    };
535	                    arr.replace(idx, new_req.render());
536	                }
537	            }
538	        }
539	
540	        Ok(())
541	    }
542	}
