544	/// Rewrites a PEP 508 dependency constraint to pin it to `target`.
545	///
546	/// The following single-clause and two-clause forms are recognized and rewritten:
547	///
548	/// - `==X.Y.Z` — exact pin — is rewritten to `==NEW`.
549	/// - `~=X.Y.Z` — compatible release — is rewritten to `~=NEW`.
550	/// - `>=X.Y.Z` — lower bound only — is rewritten to `>=NEW`.
551	/// - `>=X.Y.Z,<A.B` — two-clause range — is rewritten to `>=NEW,<NEXT_MAJOR`
552	///   where `NEXT_MAJOR` equals `target.major() + 1`.
553	///
554	/// All other forms return `None` — including upper-bound-only (`<`, `<=`),
555	/// exclusion (`!=`), compound expressions beyond the two-clause range above,
556	/// wildcard `*`, and pre-release targets.  Callers must leave the original
557	/// constraint unchanged when `None` is returned.
558	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
559	    // Only Range specs are produced by iter_dependencies for Python.
560	    let original = match spec {
561	        DepSpec::Range(_, raw) => raw.as_str(),
562	        _ => return None,
563	    };
564	
565	    // Pre-release targets are not safe to rewrite automatically.
566	    if target.is_prerelease() {
567	        return None;
568	    }
569	
570	    let trimmed = original.trim();
571	
572	    // Compound range: ">=X.Y.Z,<A.B" → ">=NEW,<NEXT_MAJOR"
573	    if trimmed.contains(',') {
574	        return rewrite_range(trimmed, target);
575	    }
576	
577	    // Single-clause forms matched by their PEP 508 operator prefix.
578	    if trimmed.starts_with("==") {
579	        return rewrite_single(trimmed, "==", target);
580	    }
581	    if trimmed.starts_with("~=") {
582	        return rewrite_single(trimmed, "~=", target);
583	    }
584	    if trimmed.starts_with(">=") {
585	        return rewrite_single(trimmed, ">=", target);
586	    }
587	
588	    // Unknown or unsupported form (e.g. "<", "<=", "!=", bare "*").
589	    None
590	}
591	
592	/// Rewrites a single-clause PEP 508 specifier, preserving the operator.
593	fn rewrite_single(original: &str, op: &str, target: &Version) -> Option<DepSpec> {
594	    // Validate that the original clause parses correctly (guards against
595	    // unknown version syntax that happens to start with a known prefix).
596	    let _rest = original.strip_prefix(op)?;
597	    let maj = target.major()?;
598	    let min = target.minor()?;
599	    let pat = target.patch()?;
600	    let rendered = format!("{op}{maj}.{min}.{pat}");
601	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
602	    Some(DepSpec::Range(req, rendered))
603	}
604	
605	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
606	///
607	/// Returns `None` for anything that does not match exactly this two-clause
608	/// lower/upper pattern, including specs with three or more clauses (e.g.
609	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
610	/// a semantically incorrect constraint.
611	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
612	    // Reject any spec with more than two comma-separated clauses: rewriting
613	    // would silently discard the extra clauses, changing the semantics.
614	    if original.split(',').count() != 2 {
615	        return None;
616	    }
617	
618	    let mut parts = original.splitn(2, ',');
619	    let lower = parts.next()?.trim();
620	    let upper = parts.next()?.trim();
621	
622	    // Lower clause must be `>=…`.
623	    if !lower.starts_with(">=") {
624	        return None;
625	    }
626	    // Upper clause must be strictly `<…` (not `<=`).
627	    if !upper.starts_with('<') || upper.starts_with("<=") {
628	        return None;
629	    }
630	
631	    let maj = target.major()?;
632	    let min = target.minor()?;
633	    let pat = target.patch()?;
634	    let next_major = maj + 1;
635	    let rendered = format!(">={maj}.{min}.{pat},<{next_major}");
636	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
637	    Some(DepSpec::Range(req, rendered))
638	}
