            // vanish from the graph.
            None => DepSpec::Opaque("non-versioned dependency (path/git/url or unrecognized shape)".to_string()),
        };

        entries.push(DependencyEntry {
            name: name.to_string(),
            inherited: false,
            kind: DepKind::Runtime,
            spec,
        });
    }
}

