5	/// Builds a [`GlobSet`] from a list of glob strings, matched with
6	/// `literal_separator(true)` semantics (`*` does not cross `/`; `**` does)
7	/// against forward-slash-normalized, workspace-relative paths.
8	///
9	/// Per-entry glob-compile-failure rule: an entry that fails to compile is
10	/// skipped and treated as never-matching; every other syntactically valid
11	/// entry in the same list is still compiled and matched normally. Never
12	/// panics, never returns an error.
13	pub(crate) fn build_globset(entries: &[String]) -> GlobSet {
14	    let mut builder = GlobSetBuilder::new();
15	    for entry in entries {
16	        if let Ok(glob) = GlobBuilder::new(entry).literal_separator(true).build() {
17	            builder.add(glob);
18	        }
19	    }
20	    builder.build().unwrap_or_else(|_| GlobSet::empty())
21	}
