32	/// Workspace-membership filter shared by Cargo's `[workspace]` and uv's
33	/// `[tool.uv.workspace]` -- both use the identical members/exclude
34	/// glob-array shape, including a root manifest that is itself both a
35	/// package/project and a workspace root (hybrid root). `NpmMembership`
36	/// deliberately does NOT go through this type: npm's shape genuinely
37	/// differs (JSON not TOML, no `exclude` concept, and a pnpm-workspace.yaml
38	/// fallback with its own precedence rules).
39	pub(crate) struct Membership {
40	    members: Option<GlobSet>,
41	    exclude: GlobSet,
42	    hybrid_root: bool,
43	}
44	
45	impl Membership {
46	    /// `rel` must be a workspace-relative, forward-slash-normalized path.
47	    /// `is_root` is true exactly when `rel == Path::new(".")`.
48	    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
49	        if is_root && self.hybrid_root {
50	            return true;
51	        }
52	        if self.exclude.is_match(rel) {
53	            return false;
54	        }
55	        match &self.members {
56	            None => true,
57	            Some(members) => members.is_match(rel),
58	        }
59	    }
60	
61	    fn absent() -> Self {
62	        Membership {
63	            members: None,
64	            exclude: GlobSet::empty(),
65	            hybrid_root: false,
66	        }
67	    }
68	}
