70	/// Safely parses a TOML array-of-strings item, returning `None` for any
71	/// other shape (bare string, table, non-string entries, etc.) instead of
72	/// panicking.
73	fn parse_toml_string_array(item: &toml_edit::Item) -> Option<Vec<String>> {
74	    let arr = item.as_array()?;
75	    let mut out = Vec::with_capacity(arr.len());
76	    for v in arr.iter() {
77	        out.push(v.as_str()?.to_string());
78	    }
79	    Some(out)
80	}
