82	/// Describes where an ecosystem's workspace-membership table lives inside
83	/// its root manifest, so [`read_membership`] can walk to it generically
84	/// instead of each ecosystem hand-rolling the same members/exclude/
85	/// hybrid-root logic around a different table path.
86	pub(crate) struct MembershipSpec {
87	    /// The root manifest's file name, e.g. `Cargo.toml`.
88	    manifest_file_name: &'static str,
89	    /// Nested table keys leading to the workspace table, walked in order
90	    /// from the document root, e.g. `["workspace"]` for Cargo or
91	    /// `["tool", "uv", "workspace"]` for uv-based Python.
92	    table_path: &'static [&'static str],
93	    /// Top-level key whose co-presence with the workspace table marks a
94	    /// hybrid root, e.g. `"package"` for Cargo or `"project"` for Python.
95	    owner_key: &'static str,
96	}
97	
98	pub(crate) const CARGO_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
99	    manifest_file_name: ManifestFormat::CargoToml.file_name(),
100	    table_path: &["workspace"],
101	    owner_key: "package",
102	};
103	
104	pub(crate) const PYTHON_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
105	    manifest_file_name: ManifestFormat::PyprojectToml.file_name(),
106	    table_path: &["tool", "uv", "workspace"],
107	    owner_key: "project",
108	};
109	
110	/// NAIVE first pass: only handles (1) the manifest file entirely absent, and
111	/// (2) a well-formed workspace table with members/exclude arrays of
112	/// strings. Every other shape (workspace table absent, TOML unparseable,
113	/// members/exclude present but not an array-of-strings, members key
114	/// absent) falls back to an absent-filter (admit-all) result -- see the
115	/// `cargo_membership_tests`/`python_membership_tests` modules for the
116	/// exact fallback matrix this is pinned against.
117	pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Membership {
118	    let content = match std::fs::read_to_string(root.join(spec.manifest_file_name)) {
119	        Ok(c) => c,
120	        Err(_) => return Membership::absent(),
121	    };
122	    let doc = match content.parse::<toml_edit::DocumentMut>() {
123	        Ok(d) => d,
124	        Err(_) => return Membership::absent(),
125	    };
126	
127	    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
128	    for key in &spec.table_path[1..] {
129	        cursor = cursor.and_then(|c| c.get(*key));
130	    }
131	
132	    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
133	    let Some(workspace) = cursor else {
134	        return Membership {
135	            members: None,
136	            exclude: GlobSet::empty(),
137	            hybrid_root,
138	        };
139	    };
140	    let members = workspace
141	        .get("members")
142	        .and_then(parse_toml_string_array)
143	        .map(|v| build_globset(&v));
144	    let exclude = workspace
145	        .get("exclude")
146	        .and_then(parse_toml_string_array)
147	        .map(|v| build_globset(&v))
148	        .unwrap_or_else(GlobSet::empty);
149	    Membership {
150	        members,
151	        exclude,
152	        hybrid_root,
153	    }
154	}
