271	impl NpmMembership {
272	    /// `rel` must be a workspace-relative, forward-slash-normalized path.
273	    /// `is_root` is true exactly when `rel == Path::new(".")`.
274	    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
275	        if is_root && self.hybrid_root {
