285	/// True when the root package.json exists, parses as JSON, and declares a
286	/// "name" field. Independent of which arm (package.json "workspaces" or a
287	/// sibling pnpm-workspace.yaml) governs the rest of npm membership -- see
288	/// AC-16/AC-16b/AC-17/AC-10d.
289	fn package_json_declares_name(root: &Path) -> bool {
290	    let Ok(content) = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())) else {
291	        return false;
292	    };
293	    let Ok(val) = serde_json::from_str::<serde_json::Value>(&content) else {
294	        return false;
295	    };
296	    val.get("name").is_some()
297	}
298	
299	pub(crate) fn read_npm_membership(root: &Path) -> NpmMembership {
300	    let hybrid_root = package_json_declares_name(root);
301	    if let Some(packages) = read_pnpm_packages(root) {
302	        return NpmMembership {
303	            globs: Some(build_globset(&packages)),
304	            hybrid_root,
305	        };
306	    }
307	    NpmMembership {
308	        globs: read_package_json_workspaces(root).map(|v| build_globset(&v)),
309	        hybrid_root,
310	    }
311	}
