313	/// YAML-parse-Err, zero-documents, packages-key-missing-or-wrong-shape, and
314	/// a non-string sequence element all safely fall back to `None` (which
315	/// causes `read_npm_membership` to fall through to
316	/// `read_package_json_workspaces` or admit-all).
317	fn read_pnpm_packages(root: &Path) -> Option<Vec<String>> {
318	    let content = std::fs::read_to_string(root.join("pnpm-workspace.yaml")).ok()?;
319	    let docs = yaml_rust2::YamlLoader::load_from_str(&content).ok()?;
320	    let doc = docs.first()?;
321	    let packages = doc["packages"].as_vec()?;
322	    let mut out = Vec::with_capacity(packages.len());
323	    for item in packages {
324	        out.push(item.as_str()?.to_string());
325	    }
326	    Some(out)
327	}
