329	/// File-absent, field-absent, non-array "workspaces", and non-string array
330	/// entries all safely fall back to `None` (a plain `?`-chain), which causes
331	/// `read_npm_membership` to admit-all.
332	fn read_package_json_workspaces(root: &Path) -> Option<Vec<String>> {
333	    let content = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())).ok()?;
334	    let val: serde_json::Value = serde_json::from_str(&content).ok()?;
335	    let field = val.get("workspaces")?;
336	    let arr = field.as_array()?;
337	    let mut out = Vec::with_capacity(arr.len());
338	    for v in arr {
339	        out.push(v.as_str()?.to_string());
340	    }
341	    Some(out)
342	}
